// LinkifyText.tsx
// Built-in runtime for Label `linkable`: auto-links BARE http(s) URLs and
// phone numbers found in the text (attribute_definitions Label/linkable).
// Runtime detection is what makes the declaration work for BOUND text —
// a build-time split can only ever see literal strings
// (rjui-label-linkable-binding-renders-raw).
// Generated by ReactJsonUI

import React from 'react';

interface LinkifyTextProps {
  text?: string;
  id?: string;
  className?: string;
  // Common attribute surface the converter can emit onto any component —
  // kept in lockstep with the built-in props contract spec.
  style?: React.CSSProperties;
  onClick?: () => void;
  'data-testid'?: string;
  'data-tag'?: string;
}

// Bare http(s) URLs. Trailing sentence punctuation is not part of the link.
const URL_PATTERN = /https?:\/\/[^\s]+/g;

// Phone candidates: digit runs with separators (spaces, hyphens, dots,
// parentheses), optional leading +. Candidates are then validated by digit
// count (8–15, ITU E.164 ceiling) so prices, years and IDs stay plain text.
const PHONE_PATTERN = /\+?\d[\d\-.() ]{5,}\d/g;

const MIN_PHONE_DIGITS = 8;
const MAX_PHONE_DIGITS = 15;

function isPhoneNumber(candidate: string): boolean {
  const digits = candidate.replace(/\D/g, '');
  return digits.length >= MIN_PHONE_DIGITS && digits.length <= MAX_PHONE_DIGITS;
}

// tel: href is rebuilt from ONLY digits and a leading '+' — never from the
// matched text itself, so a crafted value cannot smuggle another scheme or
// separator garbage into the href.
function telHref(candidate: string): string {
  const plus = candidate.trim().startsWith('+') ? '+' : '';
  return `tel:${plus}${candidate.replace(/\D/g, '')}`;
}

function stripTrailingPunctuation(url: string): [string, string] {
  const match = url.match(/[.,;:!?)\]]+$/);
  if (!match) return [url, ''];
  return [url.slice(0, url.length - match[0].length), match[0]];
}

type Segment =
  | { kind: 'text'; value: string }
  | { kind: 'url'; value: string }
  | { kind: 'phone'; value: string };

function segment(text: string): Segment[] {
  const segments: Segment[] = [];
  // One combined scan keeps original ordering; URL wins where both could
  // start at the same index (a URL may contain long digit runs).
  const combined = new RegExp(`(${URL_PATTERN.source})|(${PHONE_PATTERN.source})`, 'g');
  let cursor = 0;
  for (const match of text.matchAll(combined)) {
    const index = match.index ?? 0;
    if (index > cursor) segments.push({ kind: 'text', value: text.slice(cursor, index) });
    if (match[1] !== undefined) {
      const [url, trailing] = stripTrailingPunctuation(match[1]);
      segments.push({ kind: 'url', value: url });
      if (trailing) segments.push({ kind: 'text', value: trailing });
    } else if (isPhoneNumber(match[2])) {
      segments.push({ kind: 'phone', value: match[2] });
    } else {
      segments.push({ kind: 'text', value: match[2] });
    }
    cursor = index + match[0].length;
  }
  if (cursor < text.length) segments.push({ kind: 'text', value: text.slice(cursor) });
  return segments;
}

const LINK_CLASS = 'text-blue-500 underline';

// forwardRef: the converter rides the autoShrink measurement ref on the same
// element that holds the text, whatever the render shape.
export const LinkifyText = React.forwardRef<HTMLSpanElement, LinkifyTextProps>(({
  text = '',
  id,
  className = '',
  style,
  onClick,
  'data-testid': dataTestid,
  'data-tag': dataTag,
}, ref) => (
  // whitespace-pre-line preserves newlines carried by bound values — the
  // literal path used to lose them too, so both shapes get it here.
  <span
    ref={ref}
    id={id}
    className={`${className} whitespace-pre-line`}
    style={style}
    onClick={onClick}
    data-testid={dataTestid}
    data-tag={dataTag}
    data-linkable="true"
  >
    {segment(text).map((seg, i) => {
      if (seg.kind === 'url') {
        return (
          <a key={i} href={seg.value} target="_blank" rel="noopener noreferrer" className={LINK_CLASS}>
            {seg.value}
          </a>
        );
      }
      if (seg.kind === 'phone') {
        return (
          <a key={i} href={telHref(seg.value)} className={LINK_CLASS}>
            {seg.value}
          </a>
        );
      }
      return <React.Fragment key={i}>{seg.value}</React.Fragment>;
    })}
  </span>
));

LinkifyText.displayName = 'LinkifyText';

export default LinkifyText;
